// Le nom du PDF porte le millésime du recensement et change chaque année ;
// la page d'index, elle, est stable. Même principe que la FH et que le
// classeur SIPRI : on déclare la page, on résout le lien. Reconstruire
// l'URL par calcul supposerait de connaître la convention de nommage du
// producteur, qui n'est pas documentée.
//
// L'URL résolue est consignée : elle fait partie de la trace d'audit.
const page = $json.data ?? $json.body ?? '';
const liens = [...String(page).matchAll(/href="([^"]*Recensement[^"]*\.pdf)"/gi)].map(m => m[1]);
if (!liens.length) {
  throw new Error("Aucun lien de recensement trouvé sur la page d'index — la source a changé de forme, incident à consigner plutôt qu'à contourner.");
}
// Le plus récent : le millésime le plus élevé présent dans le nom.
const avecMillesime = liens.map(u => ({ u, an: Math.max(0, ...[...u.matchAll(/20(\d{2})/g)].map(m => 2000 + Number(m[1]))) }));
avecMillesime.sort((a, b) => b.an - a.an);
// `URL` n'est pas exposé dans le bac à sable du moteur de code de
// l'orchestrateur — même constat que `URLSearchParams` dans `collecte_flux`.
// La résolution du lien relatif est donc faite à la main, sans dépendance.
function resoudreLien(href, base) {
  const h = String(href || '').trim().replace(/&amp;/g, '&');
  if (/^https?:\/\//i.test(h)) return h;
  if (h.startsWith('//')) return 'https:' + h;
  const m = String(base).match(/^(https?:\/\/[^\/]+)(\/[^?#]*)?/i);
  if (!m) {
    throw new Error("Base de résolution invalide : " + base);
  }
  const racine = m[1];
  if (h.startsWith('/')) return racine + h;
  const dossier = (m[2] || '/').replace(/[^\/]*$/, '');
  // Réduction des segments « . » et « .. », comme le ferait `URL`.
  const segments = [];
  for (const s of (dossier + h).split('/')) {
    if (s === '.') continue;
    if (s === '..') { segments.pop(); continue; }
    segments.push(s);
  }
  return racine + segments.join('/');
}
const url = resoudreLien(avecMillesime[0].u, 'https://cpih.ch/');
return [{ json: { url_resolue: url, millesime: String(avecMillesime[0].an), candidats: liens.length } }];

// VOIE MULTIMODALE, et le motif est mesuré, pas supposé.
//
// Le nœud de lecture PDF de l'orchestrateur ne peut pas rendre ce tableau :
// sa fonction parseText parcourt les fragments dans l'ordre du flux de
// contenu, ne se sert de la coordonnée Y que pour couper les lignes, et
// JETTE la coordonnée X. Le PDF de la Convention patronale étant composé
// colonne par colonne, la sortie est mélangée — mesuré le 30.08.2026 :
// concordance positionnelle 2/14 sur « de direction », 0/7 sur « Total »,
// 0/1 sur « Entreprises », et l'année 2009 sort avant 2008.
//
// On ne soumet donc PAS le texte extrait : on soumet le PDF ENTIER, que
// les trois éditeurs lisent en vision. C'est la différence avec le
// communiqué ACEA, dont le texte en prose arrive intact.
// Le binaire n'est PAS inline. Cette instance stocke en mode `filesystem-v2` :
// `binary.data.data` ne contient que le marqueur « filesystem-v2 » (13 caractères)
// et le PDF vit sur disque, référencé par `binary.data.id`. Envoyer ce champ tel
// quel produisait « data:application/pdf;base64,filesystem-v2 », d'où le refus
// d'OpenAI (400, invalid_value sur file_data) — constaté le 31.08.2026 par sonde.
// La voie supportée sous task runner est l'appel RPC `getBinaryDataBuffer`.
const meta = $input.first().binary?.data;
if (!meta) {
  throw new Error("Aucun binaire sur l'item : le téléchargement du PDF n'a rien produit.");
}
const buf = await this.helpers.getBinaryDataBuffer(0, 'data');
// Le document soumis aux trois modèles doit être le PDF, et on le vérifie plutôt
// que de le supposer : un contenu muet expédié aux trois éditeurs coûte trois
// appels et rend un résultat faux sans rien signaler.
if (buf.length < 10000 || buf.slice(0, 5).toString('latin1') !== '%PDF-') {
  throw new Error(`Le contenu téléchargé n'est pas un PDF exploitable (${buf.length} octets, en-tête « ${buf.slice(0, 8).toString('latin1')} ») — source modifiée ou réponse d'erreur, incident à instruire.`);
}
const b64 = buf.toString('base64');

const consigne = `Tu es un extracteur de données. Le document joint est le « Recensement du personnel et des entreprises des industries horlogère et microtechnique suisses » de la Convention patronale.

Extrais INTÉGRALEMENT le tableau « Tb. 1e — EFFECTIFS ET ENTREPRISES / evolution dans le temps ».

Renvoie STRICTEMENT un objet JSON valide, sans texte autour et sans balises de code, de la forme :
{"lignes": [{"annee": "2005", "direction": 1433, "administratif": 8810, "production": 31000, "sous_total": 41243, "a_domicile": 485, "total": 41728, "entreprises": 593}, ...]}

Règles impératives :
- Une entrée par ligne du tableau, dans l'ordre du document, de la première année à la dernière.
- Recopie les nombres TELS QU'IMPRIMÉS, sans les recalculer, sans les corriger, sans apostrophe de milliers.
- L'année 2013 figure DEUX FOIS (deux variantes de la colonne Entreprises) : rends les deux lignes, dans l'ordre, en nommant la première "2013a" et la seconde "2013b".
- N'utilise AUCUNE source autre que le document joint. Si une valeur est illisible, mets null.`;

return [{ json: {
  b64,
  consigne,
  run_id: $('Ouvrir le run').first().json.run_id,
  source_doc: $('Extraire l\'URL du PDF').first().json.url_resolue
} }];

// TROIS CONTRÔLES, TOUS AVANT ÉCRITURE, ET DEUX CONDITIONS INDÉPENDANTES.
//
// 1. CONSENSUS — part des modèles d'accord sur la valeur, calculée par
//    valeur modale et non par un simple booléen d'unanimité. Trois modèles
//    donnent donc 1 (3/3), 0,67 (2/3) ou 0,33 (tous différents). En cas
//    d'égalité parfaite, AUCUNE valeur ne se dégage : on ne tire pas au
//    sort, la part rendue force le passage en file.
// 2. SEUIL — lu au référentiel, jamais écrit ici (voir « Lire les seuils
//    de consensus »). Par défaut 1.0 : avec trois modèles, descendre sous
//    l'unanimité signifie « deux sur trois suffisent », or les erreurs de
//    lecture d'un tableau sont CORRÉLÉES entre modèles.
// 3. ARITHMÉTIQUE — direction + administratif + production = sous-total,
//    puis + à domicile = total. Condition INDÉPENDANTE et non contournable :
//    la règle est « consensus >= seuil ET contrôles satisfaits ». C'est ce
//    second facteur qui empêche le consensus de valoir preuve. La ligne
//    2025 le démontre : trois modèles unanimes ET exacts, et pourtant une
//    valeur à faire voir — c'est le document publié qui se trompait, et
//    aucun seuil de consensus, si haut soit-il, ne l'aurait vu.

const CH = ['direction','administratif','production','sous_total','a_domicile','total','entreprises'];

function enJson(t) {
  t = String(t || '').trim();
  if (t.startsWith('```')) { t = t.split('```')[1]; if (t.startsWith('json')) t = t.slice(4); }
  const d = t.indexOf('{'), f = t.lastIndexOf('}');
  if (d < 0 || f < 0) throw new Error('reponse non analysable');
  return JSON.parse(t.slice(d, f + 1));
}

// Valeur modale et part d'accord. Renvoie une valeur nulle si aucune ne se
// dégage : le routage s'en chargera, on ne choisit jamais au hasard.
function modale(vals) {
  const propres = vals.filter(v => v !== null && v !== undefined && v !== '');
  if (!propres.length) return { valeur: null, part: 0 };
  const compte = new Map();
  for (const v of propres) compte.set(String(v), (compte.get(String(v)) || 0) + 1);
  let tete = null, n = 0, exaequo = false;
  for (const [k, c] of compte) {
    if (c > n) { tete = k; n = c; exaequo = false; }
    else if (c === n) { exaequo = true; }
  }
  return { valeur: exaequo ? null : Number(tete), part: n / vals.length };
}

const brut = {
  openai: (() => { const o = $('Modèle A (OpenAI)').first().json; return (o.output || []).flatMap(i => i.content || []).filter(p => p.type === 'output_text' || p.type === 'text').map(p => p.text).join(''); })(),
  anthropic: (() => { const o = $('Modèle B (Anthropic)').first().json; return (o.content || []).filter(b => b.type === 'text').map(b => b.text).join(''); })(),
  google: (() => { const o = $('Modèle C (Google)').first().json; return ((o.candidates || [])[0]?.content?.parts || []).filter(p => p.text).map(p => p.text).join(''); })()
};

const lectures = {}; const incidentsModele = [];
for (const [nom, txt] of Object.entries(brut)) {
  try { lectures[nom] = Object.fromEntries(enJson(txt).lignes.map(l => [String(l.annee), l])); }
  catch (e) { incidentsModele.push(`${nom} : ${e.message}`); }
}
const modeles = Object.keys(lectures);
if (modeles.length < 2) throw new Error('Moins de deux lectures exploitables : ' + incidentsModele.join(' | '));

// Seuils déclarés au référentiel. L'absence de seuil n'ouvre pas la porte :
// on retombe sur l'unanimité, jamais sur « pas de contrainte ».
const seuilsBruts = $('Lire les seuils de consensus').first().json.seuils || {};
const seuilDe = (ind) => { const s = Number(seuilsBruts[ind]); return Number.isFinite(s) && s > 0 ? s : 1; };

const annees = [...new Set(modeles.flatMap(m => Object.keys(lectures[m])))].sort();
const run_id = $('Préparer la charge').first().json.run_id;
const source_doc = $('Préparer la charge').first().json.source_doc;
const sortie = [];

for (const a of annees) {
  const cell = {};
  for (const c of CH) cell[c] = modale(modeles.map(m => lectures[m][a]?.[c] ?? null));

  const v = (c) => cell[c].valeur;
  const somme = (v('direction') ?? 0) + (v('administratif') ?? 0) + (v('production') ?? 0);
  const arith = somme === v('sous_total') && somme + (v('a_domicile') ?? 0) === v('total');
  const incidents = [...incidentsModele];
  if (!arith) incidents.push(`controle arithmetique : direction+administratif+production = ${somme}, sous-total imprime = ${v('sous_total')} (ecart ${v('sous_total') - somme})`);

  const pousser = (indicator_id, champ) => {
    const { valeur, part } = cell[champ];
    const seuil = seuilDe(indicator_id);
    if (part < seuil) incidents.push(`consensus ${Math.round(part * 100)} % sous le seuil declare de ${Math.round(seuil * 100)} % sur « ${champ} »`);
    sortie.push({ json: {
      indicator_id, run_id, period: a.slice(0, 4), geo: 'CH',
      value: valeur, consensus_score: Number(part.toFixed(4)), seuil_applique: seuil,
      arith, diffusable: valeur !== null && part >= seuil && arith,
      source_doc, champ_retenu: champ,
      detail: Object.fromEntries(CH.map(c => [c, cell[c]])),
      valeurs_par_modele: Object.fromEntries(modeles.map(m => [m, lectures[m][a]?.[champ] ?? null])),
      incidents
    } });
  };

  // H2 = effectifs (colonne Total a-d). Le doublon 2013 porte les MÊMES
  // effectifs : une seule écriture, sur la variante a.
  if (a !== '2013b') pousser('H2', 'total');

  // H11 = entreprises. RUPTURE DE DÉFINITION : la note (2) du tableau
  // indique que la variante AVEC succursales fait foi dès 2014 ; la série
  // homogène commence donc à 2013b. Écrire 2005-2012 fabriquerait un saut
  // d'environ 17 % sans réalité économique.
  const an = Number(a.slice(0, 4));
  if (a === '2013b' || (an >= 2014 && a.length === 4)) pousser('H11', 'entreprises');
}
return sortie;
